import numpy as np


def _record(name, value):
    # wrapper to ensure exactly one record per description
    probe(name, value)


def run():
    # 1
    name = "Series/DataFrame of datetime64 or timedelta64 cast to SparseDtype(values.dtype) then .to_json(date_format=\"epoch\", date_unit=unit) for unit in ['s','ms','us','ns'] (values = DatetimeIndex([...]).as_unit('us'))"
    try:
        unit_results = {}
        values = pd.DatetimeIndex(["1970-01-01"]).as_unit("us")
        sparse = pd.SparseDtype(values.dtype)
        ser = pd.Series(values.astype(sparse))
        for unit in ["s", "ms", "us", "ns"]:
            unit_results[unit] = ser.to_json(date_format="epoch", date_unit=unit)
        _record(name, unit_results)
    except Exception as e:
        probe_exception(name, e)

    # 2
    name = "DatetimeIndex([\"1969-12-31 23:59:59.500000\",\"1970-01-01 00:00:00.500000\"]).as_unit(\"us\") as CategoricalIndex index/columns, .to_json(date_format=\"epoch\", date_unit=unit), unit in ['s','ms','us','ns']"
    try:
        idx = pd.DatetimeIndex(
            ["1969-12-31 23:59:59.500000", "1970-01-01 00:00:00.500000"]
        ).as_unit("us")
        cat_idx = pd.CategoricalIndex(idx)
        df = pd.DataFrame({"A": [1, 2]}, index=cat_idx)
        unit_results = {}
        for unit in ["s", "ms", "us", "ns"]:
            unit_results[unit] = df.to_json(date_format="epoch", date_unit=unit)
        _record(name, unit_results)
    except Exception as e:
        probe_exception(name, e)

    # 3
    name = "DatetimeIndex([\"9999-01-01\"]).as_unit(\"s\") cast to 'category' or SparseDtype(values.dtype), .to_json(date_format=\"epoch\", date_unit=\"ns\")"
    try:
        values = pd.DatetimeIndex(["9999-01-01"]).as_unit("s")
        # cast to SparseDtype(values.dtype) (also satisfies 'category' alternative)
        sparse = pd.SparseDtype(values.dtype)
        ser = pd.Series(values.astype(sparse))
        out = ser.to_json(date_format="epoch", date_unit="ns")
        _record(name, out)
    except Exception as e:
        probe_exception(name, e)

    # 4
    name = "pd.CategoricalIndex(DatetimeIndex([\"9999-01-01\"]).as_unit(\"s\")) used as index or columns of DataFrame([[1]]) with .to_json(orient=orient, date_format=\"epoch\", date_unit=\"ns\"), orient in ['index','columns','split']"
    try:
        cat = pd.CategoricalIndex(pd.DatetimeIndex(["9999-01-01"]).as_unit("s"))
        unit_results = {}
        for orient in ["index", "columns", "split"]:
            df = pd.DataFrame([[1]], index=cat)
            unit_results[orient] = df.to_json(
                orient=orient, date_format="epoch", date_unit="ns"
            )
        _record(name, unit_results)
    except Exception as e:
        probe_exception(name, e)


run()

